// Bundles the agent policy hook (server/modules/agent-policy/hook/main.ts plus
// its rules and server/git-guardrails.ts) into ONE dependency-free CommonJS
// script and embeds it as a string in a generated TypeScript module. The server
// writes that string to ~/.specrails/agent-policy/ at run time, so the hook
// ships identically in development, the npm package and the packaged sidecar
// without a separate resource.
//
//   node scripts/build-policy-hook.mjs          regenerate
//   node scripts/build-policy-hook.mjs --check  fail when the generated file is stale
import { build } from 'esbuild'
import { createHash } from 'node:crypto'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const entry = path.join(root, 'server', 'modules', 'agent-policy', 'hook', 'main.ts')
const target = path.join(root, 'server', 'modules', 'agent-policy', 'hook', 'policy-hook-bundle.generated.ts')

export async function renderPolicyHookModule() {
  const result = await build({
    entryPoints: [entry],
    bundle: true,
    platform: 'node',
    format: 'cjs',
    target: 'node18',
    write: false,
    legalComments: 'none',
    charset: 'utf8',
    logLevel: 'silent',
  })
  const source = `// Specrails agent policy hook (generated; do not edit).\n${result.outputFiles[0].text}`
  const version = createHash('sha256').update(source).digest('hex').slice(0, 12)
  return [
    '// GENERATED by scripts/build-policy-hook.mjs from server/modules/agent-policy/hook/main.ts.',
    '// Do not edit. Regenerate with `npm run build:policy-hook`.',
    '/* eslint-disable */',
    `export const POLICY_HOOK_VERSION = ${JSON.stringify(version)}`,
    `export const POLICY_HOOK_SOURCE = ${JSON.stringify(source)}`,
    '',
  ].join('\n')
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const output = await renderPolicyHookModule()
  if (process.argv.includes('--check')) {
    const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8').replace(/\r\n/g, '\n') : ''
    if (current !== output) {
      console.error('[build-policy-hook] policy-hook-bundle.generated.ts is stale. Run `npm run build:policy-hook`.')
      process.exitCode = 1
    }
  } else {
    fs.writeFileSync(target, output)
    console.log(`[build-policy-hook] wrote ${path.relative(root, target)}`)
  }
}
